//! Parity of kernel trees, GPyTorch's and BoTorch's kernels, priors and
//! constraints in `SingleTaskGP` with BoTorch (fixtures in
//! `tests/fixtures/6a_kernels/*.json`, generated by
//! `scripts/generate_fixtures.py --phase 6a-kernels`).
//!
//! Every fixture describes its `covar_module` as a JSON spec (GPyTorch /
//! BoTorch class names and keyword arguments, see
//! `botorch_pyo3/tests/kernel_tree_helpers.py`), from which this test builds
//! the same [`KernelNode`] tree, and records BoTorch's
//!
//! * parameter names, shapes and optimizer bounds (exact) and default raw
//!   parameters (exact, except the random initial values of index kernels,
//!   which the test takes from the fixture);
//! * MLL values (1e-9, relative) and gradients (1e-8, relative to the largest
//!   component) at the default and at random raw parameters, and the prior
//!   kernel matrix at the random parameters (1e-9);
//! * `q = 1` posterior means and variances (GPyTorch's `diag=True` mode), with
//!   and without observation noise, and their gradients with respect to the
//!   inputs; joint `q = 3` posteriors per output and the gradient of a
//!   weighted sum of their means and covariances (1e-9 values, 1e-8
//!   gradients);
//! * `fit_gpytorch_mll` from the default parameters, compared with BoTorch's
//!   outcomes on the model and its twins (training inputs perturbed at
//!   1e-14 .. 1e-11; first attempts only: retries start from prior samples
//!   drawn by different generators) in two stages (`common::compare_fits`):
//!   on 16 twins, botorch_rs's best final loss (on the same twins) must
//!   reach BoTorch's best and none of its fits may end above BoTorch's
//!   worst outcome, within max(1e-6, 10 × the spread of BoTorch's outcomes
//!   at its best optimum); if not, statistically on 64 twins (a one-sided
//!   Mann-Whitney U test at level 1e-3 and botorch_rs's best within
//!   BoTorch's best `k`).
//!   botorch_rs's first attempts must not fail (end in a retry) more often
//!   than BoTorch's on the same fits (a one-sided Fisher exact test at
//!   level 1e-3, on all 64 twins when botorch_rs's first attempts fail
//!   more often on the deciding stage's fits;
//!   `common::compare_fits_and_first_attempts`).
//!
//! Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;

use botorch_core::{
    fit_gpytorch_mll, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, FitOptions, Matrix,
    OutcomeTransformChoice, Vector,
};
use common::kernel_spec::{flatten_value, node, num};
use common::{fixture_dir, matrix, rel_err, Report};
use serde::Deserialize;
use serde_json::Value;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;

#[derive(Deserialize)]
struct Mll {
    value: Vec<f64>,
    grad: Vec<f64>,
}

#[derive(Deserialize)]
struct PosteriorFixture {
    x: Vec<Vec<f64>>,
    mean: Vec<Vec<f64>>,
    variance: Vec<Vec<f64>>,
    variance_noisy: Vec<Vec<f64>>,
    dmean_dx: Vec<Vec<f64>>,
    dvariance_dx: Vec<Vec<f64>>,
    joint_x: Vec<Vec<f64>>,
    joint_mean: Vec<Vec<f64>>,
    joint_covariance: Vec<Vec<Vec<f64>>>,
    joint_covariance_noisy: Vec<Vec<Vec<f64>>>,
    weights_mean: Vec<Vec<f64>>,
    weights_cov: Vec<Vec<Vec<f64>>>,
    djoint_dx: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct Fit {
    loss: f64,
    iterations: usize,
    attempts: usize,
    raw_params: Vec<f64>,
    twin_train_x: Vec<Vec<Vec<f64>>>,
    twin_losses: Vec<f64>,
    twin_attempts: Vec<usize>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    spec: Value,
    m: usize,
    fixed_noise: bool,
    standardize: bool,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    train_yvar: Option<Vec<Vec<f64>>>,
    param_names: Vec<(String, Vec<usize>)>,
    bounds: Vec<(Value, Value)>,
    default_raw: Vec<f64>,
    default_mll: Mll,
    raw: Vec<f64>,
    mll: Mll,
    k_train: Value,
    posterior: PosteriorFixture,
    fit: Option<Fit>,
}

// ----------------------------------------------------------------------
// The test
// ----------------------------------------------------------------------

fn load() -> Vec<Case> {
    let dir: PathBuf = fixture_dir().join("6a_kernels");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no 6a_kernels fixtures");
    paths
        .iter()
        .map(|p| {
            let text = std::fs::read_to_string(p).unwrap();
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
        })
        .collect()
}

fn build(c: &Case, train_x: &[Vec<f64>]) -> BatchedMultiOutputGP {
    let options = BatchedMultiOutputGPOptions {
        train_yvar: c
            .train_yvar
            .as_ref()
            .filter(|_| c.fixed_noise)
            .map(|v| vec![matrix(v)]),
        outcome_transform: if c.standardize {
            OutcomeTransformChoice::Default
        } else {
            OutcomeTransformChoice::None
        },
        covar_tree: Some(node(&c.spec)),
        ..Default::default()
    };
    BatchedMultiOutputGP::new(
        vec![matrix(train_x)],
        vec![matrix(&c.train_y)],
        Vec::new(),
        options,
    )
    .unwrap()
}

/// Whether a parameter is initialized randomly by GPyTorch.
fn random_init(name: &str) -> bool {
    name.ends_with("covar_factor") || name.ends_with(".raw_var")
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-300);
    a.iter()
        .zip(e)
        .map(|(x, y)| (x - y).abs() / scale)
        .fold(0.0, f64::max)
}

#[test]
fn kernel_trees_match_botorch() {
    let mut report = Report::default();
    for c in load() {
        let name = c.name.as_str();
        let mut gp = build(&c, &c.train_x);
        let shapes = gp.parameter_shapes();
        assert_eq!(shapes, c.param_names, "{name}: parameter names and shapes");
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|(a, b)| (num(a), num(b))).collect();
        let rs_bounds = gp.raw_parameter_bounds();
        let bounds_ok = rs_bounds
            .iter()
            .zip(&bounds)
            .all(|(a, b)| a.0 == b.0 && a.1 == b.1);
        report.check(name, "bounds (exact)", f64::from(u8::from(!bounds_ok)), 0.0);
        // Default raw parameters (except GPyTorch's random initial values).
        let init = gp.raw_parameters();
        let mut off = 0;
        let mut init_err = 0.0f64;
        for (pname, shape) in &shapes {
            let k: usize = shape.iter().product();
            if !random_init(pname) {
                for j in off..off + k {
                    init_err = init_err.max((init[j] - c.default_raw[j]).abs());
                }
            }
            off += k;
        }
        report.check(name, "default raw parameters", init_err, 0.0);
        gp.set_raw_parameters(&c.default_raw).unwrap();
        let (v, g) = gp.mll_values_and_grad(&c.default_raw).unwrap();
        report.check_slices(name, "default MLL", &v, &c.default_mll.value, VALUE_TOL);
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );
        // Random parameters.
        gp.set_raw_parameters(&c.raw).unwrap();
        let (v, g) = gp.mll_values_and_grad(&c.raw).unwrap();
        report.check_slices(name, "MLL", &v, &c.mll.value, VALUE_TOL);
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        let k_expected: Vec<f64> = flatten_value(&c.k_train);
        let mut k_actual = Vec::new();
        for e in 0..gp.num_elements() {
            let el = &gp.models()[e];
            let covar = el.covar().unwrap();
            let p = covar.prepare(el.transformed_train_inputs()).unwrap();
            let k = covar.symmetric(&p);
            k_actual.extend(common::matrix_rows(&k));
        }
        report.check_slices(name, "kernel matrix", &k_actual, &k_expected, VALUE_TOL);

        // q = 1 posteriors (diag=True mode) and their input gradients.
        let pf = &c.posterior;
        let m = c.m;
        let (mut mean, mut var, mut var_noisy) = (Vec::new(), Vec::new(), Vec::new());
        let (mut dmean, mut dvar) = (vec![0.0; pf.x.len() * pf.x[0].len()], Vec::new());
        dvar.resize(dmean.len(), 0.0);
        let d = pf.x[0].len();
        for (i, x) in pf.x.iter().enumerate() {
            for t in 0..m {
                let gp_t = gp.model(0, t);
                let (mu, v, dm, dv) = gp_t.posterior_q1_with_grad(x).unwrap();
                mean.push(mu);
                var.push(v);
                var_noisy.push(v + gp_t.observation_noise());
                for j in 0..d {
                    dmean[i * d + j] += dm[j];
                    dvar[i * d + j] += dv[j];
                }
            }
        }
        report.check_slices(
            name,
            "q=1 posterior mean",
            &mean,
            &common::flatten(&pf.mean),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "q=1 posterior variance",
            &var,
            &common::flatten(&pf.variance),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "q=1 noisy posterior variance",
            &var_noisy,
            &common::flatten(&pf.variance_noisy),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 d mean / dx",
            grad_err(&dmean, &common::flatten(&pf.dmean_dx)),
            GRAD_TOL,
        );
        report.check(
            name,
            "q=1 d variance / dx",
            grad_err(&dvar, &common::flatten(&pf.dvariance_dx)),
            GRAD_TOL,
        );

        // Joint q = 3 posteriors per output and the gradient of a weighted sum.
        let xj = matrix(&pf.joint_x);
        let q = xj.nrows();
        let mut grad = Matrix::zeros(q, d);
        for t in 0..m {
            let gp_t = gp.model(0, t);
            let post = gp_t.posterior(&xj, false).unwrap();
            let noisy = gp_t.posterior(&xj, true).unwrap();
            report.check_slices(
                name,
                "joint posterior mean",
                post.mean.as_slice(),
                &pf.joint_mean[t],
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint posterior covariance",
                &common::matrix_rows(&post.covariance),
                &common::flatten(&pf.joint_covariance[t]),
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint noisy posterior covariance",
                &common::matrix_rows(&noisy.covariance),
                &common::flatten(&pf.joint_covariance_noisy[t]),
                VALUE_TOL,
            );
            let wm = Vector::from_vec(pf.weights_mean[t].clone());
            let wc = matrix(&pf.weights_cov[t]);
            grad += gp_t.joint_posterior_vjp(&xj, 0..q, &wm, &wc).unwrap();
        }
        report.check(
            name,
            "joint d (weighted sum) / dx",
            grad_err(&common::matrix_rows(&grad), &common::flatten(&pf.djoint_dx)),
            GRAD_TOL,
        );

        // Fits from the default parameters.
        if let Some(f) = &c.fit {
            let mut fitted = build(&c, &c.train_x);
            fitted.set_raw_parameters(&c.default_raw).unwrap();
            let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
            let own_attempts = r.results[0].attempts;
            let bt: Vec<common::FitOutcome> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .collect();
            let cmp = common::compare_fits_and_first_attempts(
                &mut report,
                name,
                "fit",
                &bt,
                &[],
                (r.loss, own_attempts),
                &mut |t| {
                    let mut twin = build(&c, &f.twin_train_x[t - 1]);
                    twin.set_raw_parameters(&c.default_raw).unwrap();
                    let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
                    (t.loss, t.results[0].attempts)
                },
            );
            let (bt_best, bt_worst) = cmp.bt_range();
            let diff = fitted
                .raw_parameters()
                .iter()
                .zip(&f.raw_params)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            println!(
                "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 attempts {own_attempts} (BoTorch {}), max parameter difference {diff:.1e}, \
                 stage {}: first-attempt outcomes: BoTorch [{bt_best:+.10}, {bt_worst:+.10}] \
                 ({} of {}), botorch_rs best {:+.10} ({} of {}), spread {:.1e}",
                r.loss,
                f.loss,
                r.results[0].iterations,
                f.iterations,
                f.attempts,
                cmp.stage(),
                cmp.bt.len(),
                cmp.twins + 1,
                cmp.rs_best(),
                cmp.rs.len(),
                cmp.twins + 1,
                cmp.spread
            );
        }
    }
    report.finish("6a kernels: kernel trees in SingleTaskGP");
}

